const CodeBlocks = (function() { 'use strict'; const config = { autoCollapse: true, collapseThreshold: 20, showLineNumbers: true, defaultCollapsed: true }; function init() { initCodeBlocks(); initCollapsibleSections(); if (config.autoCollapse) { autoCollapseLongCodeBlocks(); } console.log('[CodeBlocks] 初始化完成'); } function initCodeBlocks() { const codeBlocks = document.querySelectorAll('pre'); codeBlocks.forEach(function(pre) { if (pre.querySelector('.code-header')) { return; } const container = createCodeBlockContainer(pre); addCollapseFunctionality(container, pre); if (config.showLineNumbers) { addLineNumbers(container); } if (config.defaultCollapsed) { collapseBlock(container); } }); } function createCodeBlockContainer(pre) { const container = document.createElement('div'); container.className = 'code-block'; const header = document.createElement('div'); header.className = 'code-header'; const title = document.createElement('span'); title.className = 'code-title'; title.textContent = getCodeLanguage(pre) || 'Go 代码'; header.appendChild(title); const toggleBtn = document.createElement('button'); toggleBtn.className = 'code-toggle'; toggleBtn.innerHTML = '<span class="icon">▼</span> 折叠'; header.appendChild(toggleBtn); const content = document.createElement('div'); content.className = 'code-content'; pre.innerHTML = ''; pre.appendChild(container); container.appendChild(header); container.appendChild(content); const originalContent = pre.getAttribute('data-code') || pre.innerHTML; content.innerHTML = originalContent; return container; } function addCollapseFunctionality(container, pre) { const toggleBtn = container.querySelector('.code-toggle'); toggleBtn.addEventListener('click', function() { toggleCodeBlock(container); }); } function getCodeLanguage(pre) { const code = pre.querySelector('code'); if (code && code.className) { const match = code.className.match(/language-(\w+)/); if (match) { return match[1]; } } const content = pre.textContent; if (content.includes('package main') || content.includes('func ')) { return 'Go'; } else if (content.includes('import ') && content.includes('from ')) { return 'JavaScript/TypeScript'; } else if (content.includes('def ') || content.includes('class ')) { return 'Python'; } return null; } function addLineNumbers(container) { const content = container.querySelector('.code-content'); if (!content) return; const code = content.querySelector('code'); if (!code) return; const html = code.innerHTML; const lines = html.split('\n'); if (lines.length <= 1) return; const numberedLines = lines.map((line, index) => { return `<span class="code-line"><span class="code-line-number">${index + 1}</span>${line}</span>`; }); code.innerHTML = numberedLines.join('\n'); } function toggleCodeBlock(container) { const content = container.querySelector('.code-content'); const button = container.querySelector('.code-toggle'); if (!content || !button) return; const isCollapsed = content.classList.contains('collapsed'); if (isCollapsed) { expandBlock(content, button); } else { collapseBlock(container); } } function collapseBlock(container) { const content = container.querySelector('.code-content'); const button = container.querySelector('.code-toggle'); if (!content || !button) return; content.classList.add('collapsed'); button.classList.add('collapsed'); button.innerHTML = '<span class="icon">▼</span> 展开'; } function expandBlock(content, button) { content.classList.remove('collapsed'); button.classList.remove('collapsed'); button.innerHTML = '<span class="icon">▼</span> 折叠'; } function autoCollapseLongCodeBlocks() { const codeContents = document.querySelectorAll('.code-content'); codeContents.forEach(function(content) { const lines = content.textContent.split('\n').length; if (lines > config.collapseThreshold) { const container = content.closest('.code-block'); if (container) { collapseBlock(container); } } }); } function initCollapsibleSections() { const collapsibles = document.querySelectorAll('.collapsible'); collapsibles.forEach(function(collapsible) { const header = collapsible.querySelector('.collapsible-header'); if (!header) return; if (!header.querySelector('.icon')) { const icon = document.createElement('span'); icon.className = 'icon'; icon.textContent = '▼'; header.appendChild(icon); } header.addEventListener('click', function() { collapsible.classList.toggle('collapsed'); }); }); } function expandAll() { const buttons = document.querySelectorAll('.code-toggle.collapsed'); buttons.forEach(function(button) { const container = button.closest('.code-block'); const content = container.querySelector('.code-content'); if (content && content.classList.contains('collapsed')) { expandBlock(content, button); } }); } function collapseAll() { const buttons = document.querySelectorAll('.code-toggle:not(.collapsed)'); buttons.forEach(function(button) { const container = button.closest('.code-block'); collapseBlock(container); }); } function toggleAll() { const collapsed = document.querySelectorAll('.code-toggle.collapsed'); if (collapsed.length > 0) { expandAll(); } else { collapseAll(); } } document.addEventListener('keydown', function(e) { if ((e.ctrlKey || e.metaKey) && e.key === 'k') { e.preventDefault(); toggleAll(); } if ((e.ctrlKey || e.metaKey) && e.shiftKey && e.key === 'K') { e.preventDefault(); expandAll(); } }); return { init, expandAll, collapseAll, toggleAll, config }; })(); document.addEventListener('DOMContentLoaded', function() { CodeBlocks.init(); }); if (typeof window !== 'undefined') { window.CodeBlocks = CodeBlocks; }